generated_output:
int smallestOdd(std::vector<int> const& x) {
    if (x.empty()) {
        return 0;
    }
    std::vector<int> odds;
    for (int i = 0; i < x.size(); i++) {
        if (x[i] % 2 == 1) {
            odds.push_back(x[i]);
        }
    }
    if (odds.empty()) {
        return 0;
    }
    int min = odds[0];
    for (int i = 1; i < odds.size(); i++) {
        if (odds[i] < min) {
            min = odds[i];
        }
    }
    return min;
}

